arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: #fbfcfd;
+  --surface: #ffffff;
+  --surface-2:#f3f6f7;
+  --text:#141718;
+  --muted:#556066;
+  --border:#e3eaee;
+  --shadow: 0 10px 30px rgba(16, 24, 40, 0.08);
+
+  --brand:#02838D;
+  --brand-2:#0aa7a0;
+  --accent:#ff6b5e;
+  --amber:#ffb020;
+  --focus:#0a84ff;
+
+  --radius: 16px;
+  --radius-sm: 12px;
+  --container: 1160px;
+}
+
+*{ box-sizing:border-box; }
+html,body{ height:100%; }
+body{
+  margin:0;
+  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji","Segoe UI Emoji";
+  color:var(--text);
+  background: radial-gradient(1200px 800px at 20% -10%, rgba(2,131,141,0.10), transparent 60%),
+              radial-gradient(900px 700px at 90% 10%, rgba(255,176,32,0.10), transparent 60%),
+              var(--bg);
+  line-height:1.55;
+}
+
+a{ color:inherit; text-decoration:none; }
+a:hover{ text-decoration:underline; text-underline-offset: 4px; }
+
+.container{ width:min(var(--container), calc(100% - 40px)); margin:0 auto; }
+
+.skip-link{
+  position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden;
+}
+.skip-link:focus{
+  left:16px; top:16px; width:auto; height:auto; padding:10px 12px;
+  background:var(--surface); border:1px solid var(--border); border-radius:12px; box-shadow: var(--shadow);
+  outline:3px solid rgba(10,132,255,0.25);
+}
+
+.pill{
+  display:inline-flex; align-items:center; gap:8px;
+  padding:8px 12px; border-radius:999px;
+  background:rgba(2,131,141,0.10);
+  border:1px solid rgba(2,131,141,0.20);
+  color: #02585f;
+  font-weight:700;
+  font-size:12px;
+}
+.pill .dot{ width:8px; height:8px; border-radius:999px; background: var(--brand); }
+
+.topbar{
+  background: rgba(255,255,255,0.9);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid var(--border);
+  position: sticky;
+  top:0;
+  z-index: 50;
+}
+
+.header{
+  display:flex; align-items:center; justify-content:space-between;
+  padding: 14px 0;
+  gap: 18px;
+}
+
+.brand{
+  display:flex; align-items:center; gap:10px;
+  font-weight:900;
+  letter-spacing:-0.02em;
+}
+.brand-mark{
+  width:34px; height:34px; border-radius: 12px;
+  background: linear-gradient(135deg, var(--brand), var(--brand-2));
+  box-shadow: 0 10px 25px rgba(2,131,141,0.22);
+  position: relative;
+}
+.brand-mark:after{
+  content:"";
+  position:absolute;
+  inset:10px 9px 9px 10px;
+  border-radius:10px;
+  background: rgba(255,255,255,0.9);
+  clip-path: polygon(0 55%, 40% 55%, 40% 15%, 60% 15%, 60% 55%, 100% 55%, 100% 75%, 60% 75%, 60% 100%, 40% 100%, 40% 75%, 0 75%);
+}
+.brand span{ font-size:16px; }
+
+.nav{
+  display:flex; align-items:center; gap:2px;
+}
+.nav button{
+  border:0;
+  background: transparent;
+  font: inherit;
+  padding: 10px 12px;
+  border-radius: 12px;
+  color: var(--text);
+  cursor:pointer;
+  display:flex; align-items:center; gap:6px;
+  font-weight: 700;
+  font-size: 14px;
+}
+.nav button:hover{ background: rgba(2,131,141,0.08); }
+.nav button[aria-expanded="true"]{ background: rgba(2,131,141,0.12); }
+.chev{ width:16px; height:16px; opacity:0.7; }
+
+.header-actions{
+  display:flex; align-items:center; gap:10px;
+}
+.btn{
+  display:inline-flex; align-items:center; justify-content:center;
+  gap:10px;
+  padding: 10px 14px;
+  border-radius: 999px;
+  border: 1px solid var(--border);
+  background: var(--surface);
+  font-weight: 800;
+  font-size: 13px;
+  cursor:pointer;
+}
+.btn:hover{ box-shadow: 0 10px 26px rgba(16,24,40,0.10); }
+.btn.primary{
+  background: linear-gradient(135deg, var(--accent), #ff8f62);
+  border-color: rgba(255,107,94,0.35);
+  color: #ffffff;
+}
+.btn.ghost{ background: transparent; }
+.btn:focus{ outline: 3px solid rgba(10,132,255,0.22); outline-offset: 2px; }
+
+.search{
+  display:flex; align-items:center; gap:10px;
+  padding: 10px 12px;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  min-width: 260px;
+}
+.search input{
+  border:0; outline:0; width:100%; background: transparent;
+  font: inherit; font-size: 14px;
+}
+.kbd{ font-size: 12px; color: var(--muted); border:1px solid var(--border); padding: 2px 8px; border-radius: 10px; background: var(--surface-2); }
+
+/* Mega menu */
+.mega-wrap{ position: relative; }
+.mega{
+  position:absolute;
+  top: calc(100% + 10px);
+  left: 0;
+  right: 0;
+  background: rgba(255,255,255,0.98);
+  border: 1px solid var(--border);
+  border-radius: 18px;
+  box-shadow: var(--shadow);
+  display:none;
+  overflow:hidden;
+}
+.mega[data-open="true"]{ display:block; }
+.mega-inner{ display:grid; grid-template-columns: 260px 1fr; }
+.mega-aside{
+  padding: 18px;
+  background: linear-gradient(180deg, rgba(2,131,141,0.12), rgba(2,131,141,0.02));
+  border-right: 1px solid var(--border);
+}
+.mega-aside h3{ margin: 0 0 8px; font-size: 14px; letter-spacing:-0.01em; }
+.mega-aside p{ margin:0 0 12px; font-size: 13px; color: var(--muted); }
+.mega-grid{ padding: 18px; display:grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px 14px; }
+.mega-item{
+  display:flex; align-items:flex-start; gap:10px;
+  padding: 10px 10px;
+  border-radius: 14px;
+  border: 1px solid transparent;
+}
+.mega-item:hover{ background: rgba(2,131,141,0.06); border-color: rgba(2,131,141,0.12); text-decoration:none; }
+.mega-item .icon{
+  width: 34px; height: 34px; border-radius: 12px;
+  background: rgba(2,131,141,0.12);
+  display:grid; place-items:center;
+  flex: 0 0 auto;
+}
+.mega-item strong{ display:block; font-size: 13px; }
+.mega-item span{ display:block; font-size: 12px; color: var(--muted); margin-top:2px; }
+
+.backdrop{
+  position: fixed;
+  inset: 0;
+  background: rgba(20,23,24,0.25);
+  backdrop-filter: blur(2px);
+  opacity:0;
+  pointer-events:none;
+  transition: opacity 150ms ease;
+  z-index: 40;
+}
+.backdrop[data-open="true"]{ opacity:1; pointer-events:auto; }
+
+/* Trust ticker */
+.ticker{
+  background: linear-gradient(90deg, rgba(2,131,141,0.14), rgba(255,176,32,0.12));
+  border-bottom: 1px solid rgba(2,131,141,0.14);
+}
+.ticker-row{
+  display:flex; align-items:center; gap:18px;
+  padding: 10px 0;
+  overflow:hidden;
+}
+.ticker-label{ font-size: 12px; font-weight: 900; letter-spacing: 0.08em; color: #0b3940; text-transform: uppercase; }
+.ticker-track{ display:flex; align-items:center; gap: 14px; flex: 1; }
+.ticker-marquee{
+  display:flex;
+  gap: 14px;
+  align-items:center;
+  width: max-content;
+  animation: ticker 18s linear infinite;
+  will-change: transform;
+}
+.ticker:hover .ticker-marquee{ animation-play-state: paused; }
+.stat{
+  display:flex; align-items:center; gap:10px;
+  padding: 8px 12px;
+  border-radius: 999px;
+  background: rgba(255,255,255,0.7);
+  border: 1px solid rgba(2,131,141,0.12);
+  font-weight: 800;
+  font-size: 13px;
+}
+.stat .badge{ width: 10px; height: 10px; border-radius: 999px; background: var(--brand); box-shadow: 0 0 0 4px rgba(2,131,141,0.12); }
+@keyframes ticker{ from{ transform: translateX(0);} to{ transform: translateX(-50%);} }
+
+main{ padding: 28px 0 50px; }
+
+.section{ margin-top: 34px; }
+.section h2{
+  margin: 0 0 12px;
+  font-size: 22px;
+  letter-spacing: -0.02em;
+}
+.section .subhead{ margin: 0 0 14px; color: var(--muted); font-size: 14px; }
+
+/* Hero */
+.hero{
+  display:grid;
+  grid-template-columns: 1.35fr 0.65fr;
+  gap: 18px;
+  align-items: stretch;
+}
+.hero-card{
+  background: linear-gradient(140deg, rgba(2,131,141,0.16), rgba(2,131,141,0.02) 58%),
+              radial-gradient(1100px 500px at 20% 0%, rgba(255,176,32,0.14), transparent 55%),
+              var(--surface);
+  border: 1px solid rgba(2,131,141,0.16);
+  border-radius: calc(var(--radius) + 6px);
+  box-shadow: var(--shadow);
+  overflow:hidden;
+  position: relative;
+}
+.hero-card .inner{ padding: 24px; }
+.hero-card h1{
+  margin: 12px 0 10px;
+  font-size: 36px;
+  line-height: 1.15;
+  letter-spacing: -0.03em;
+}
+.hero-card p{ margin: 0 0 16px; color: var(--muted); max-width: 60ch; }
+.hero-meta{ display:flex; align-items:center; gap: 10px; flex-wrap: wrap; }
+.meta-chip{ font-size: 12px; font-weight: 800; color: #0b3940; background: rgba(255,255,255,0.72); border: 1px solid rgba(2,131,141,0.18); padding: 8px 10px; border-radius: 999px; }
+
+.hero-media{
+  position:absolute;
+  right: -40px;
+  bottom: -40px;
+  width: 340px;
+  height: 340px;
+  border-radius: 999px;
+  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.95), rgba(255,255,255,0.5) 42%, rgba(2,131,141,0.12) 70%, rgba(2,131,141,0.0) 78%),
+              radial-gradient(circle at 70% 70%, rgba(255,176,32,0.25), transparent 60%);
+  filter: blur(0px);
+  pointer-events:none;
+}
+.hero-badge{
+  position:absolute;
+  top: 18px;
+  right: 18px;
+  width: 112px;
+  height: 112px;
+  border-radius: 999px;
+  display:grid;
+  place-items:center;
+  background: rgba(255,255,255,0.75);
+  border: 1px solid rgba(2,131,141,0.20);
+  box-shadow: 0 14px 30px rgba(2,131,141,0.14);
+}
+.badge-inner{
+  width: 92px;
+  height: 92px;
+  border-radius: 999px;
+  background: conic-gradient(from 120deg, var(--brand), var(--brand-2), var(--amber), var(--brand));
+  display:grid;
+  place-items:center;
+}
+.badge-inner span{
+  width: 72px;
+  height: 72px;
+  border-radius: 999px;
+  background: rgba(255,255,255,0.92);
+  display:grid;
+  place-items:center;
+  font-weight: 1000;
+  font-size: 12px;
+  line-height: 1.1;
+  text-align:center;
+}
+
+.hero-side{
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: calc(var(--radius) + 6px);
+  box-shadow: var(--shadow);
+  padding: 18px;
+}
+.hero-side h3{ margin: 2px 0 8px; font-size: 16px; letter-spacing: -0.01em; }
+.trust-mini{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 10px;
+  margin-top: 12px;
+}
+.trust-mini .tile{
+  border: 1px solid var(--border);
+  background: linear-gradient(180deg, rgba(2,131,141,0.06), rgba(255,255,255,0.0));
+  border-radius: 14px;
+  padding: 10px;
+}
+.tile strong{ display:block; font-size: 14px; }
+.tile span{ display:block; font-size: 12px; color: var(--muted); margin-top: 2px; }
+
+/* Trending */
+.trending-grid{ display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
+.card{
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  box-shadow: 0 14px 28px rgba(16,24,40,0.06);
+  overflow:hidden;
+  transition: transform 140ms ease, box-shadow 140ms ease;
+}
+.card:hover{ transform: translateY(-3px); box-shadow: 0 18px 40px rgba(16,24,40,0.10); text-decoration:none; }
+.card .pad{ padding: 14px; }
+.kicker{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  font-weight: 900;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: #0b3940;
+  font-size: 11px;
+}
+.kicker .line{ width: 16px; height: 2px; background: var(--brand); border-radius: 999px; }
+.card h4{ margin: 10px 0 0; font-size: 15px; letter-spacing: -0.01em; }
+.card p{ margin: 8px 0 0; color: var(--muted); font-size: 13px; }
+.card .thumb{
+  height: 116px;
+  background: radial-gradient(500px 160px at 20% 20%, rgba(2,131,141,0.26), transparent 60%),
+              radial-gradient(500px 160px at 80% 70%, rgba(255,176,32,0.18), transparent 60%),
+              linear-gradient(180deg, rgba(255,255,255,0.0), rgba(255,255,255,0.7));
+}
+
+/* Newsletter */
+.cta{
+  background: linear-gradient(120deg, rgba(2,131,141,0.20), rgba(255,107,94,0.10)),
+              var(--surface);
+  border: 1px solid rgba(2,131,141,0.18);
+  border-radius: calc(var(--radius) + 8px);
+  box-shadow: var(--shadow);
+  padding: 22px;
+  display:grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap: 16px;
+  align-items:center;
+}
+.cta h2{ margin:0 0 6px; font-size: 22px; }
+.cta p{ margin:0; color: var(--muted); }
+.cta-form{
+  background: rgba(255,255,255,0.7);
+  border: 1px solid rgba(2,131,141,0.18);
+  border-radius: 18px;
+  padding: 14px;
+}
+.field{
+  display:flex;
+  gap: 10px;
+}
+.field input{
+  flex:1;
+  border:1px solid var(--border);
+  background: var(--surface);
+  border-radius: 14px;
+  padding: 12px 12px;
+  font: inherit;
+}
+.field input:focus{ outline: 3px solid rgba(10,132,255,0.22); border-color: rgba(10,132,255,0.55); }
+.privacy{ font-size: 12px; color: var(--muted); margin-top: 10px; }
+.form-msg{ font-size: 13px; margin-top: 10px; font-weight: 800; color: #0b3940; }
+.form-msg[hidden]{ display:none; }
+
+/* Health topics carousel */
+.row-head{ display:flex; align-items:flex-end; justify-content:space-between; gap: 12px; }
+.row-head a.viewall{ font-weight: 900; color: #0b3940; }
+.carousel{
+  position: relative;
+  margin-top: 10px;
+}
+.carousel .track{
+  display:flex;
+  gap: 12px;
+  overflow:auto;
+  scroll-behavior:smooth;
+  padding: 8px 4px 18px;
+  scrollbar-width: thin;
+}
+.carousel .track::-webkit-scrollbar{ height: 10px; }
+.carousel .track::-webkit-scrollbar-thumb{ background: rgba(2,131,141,0.22); border-radius: 999px; }
+.topic{
+  flex: 0 0 170px;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  box-shadow: 0 14px 26px rgba(16,24,40,0.06);
+  padding: 14px;
+  display:flex;
+  align-items:center;
+  gap: 12px;
+}
+.topic:hover{ text-decoration:none; border-color: rgba(2,131,141,0.25); }
+.topic .avatar{
+  width: 56px;
+  height: 56px;
+  border-radius: 999px;
+  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.95), rgba(255,255,255,0.45) 50%, rgba(2,131,141,0.22) 78%),
+              radial-gradient(circle at 70% 70%, rgba(255,176,32,0.26), transparent 65%);
+  border: 1px solid rgba(2,131,141,0.18);
+  flex: 0 0 auto;
+}
+.topic strong{ display:block; font-size: 13px; letter-spacing: -0.01em; }
+.topic span{ display:block; font-size: 12px; color: var(--muted); }
+.car-btn{
+  position:absolute;
+  top: 40%;
+  transform: translateY(-50%);
+  width: 44px; height: 44px;
+  border-radius: 999px;
+  border: 1px solid var(--border);
+  background: rgba(255,255,255,0.92);
+  box-shadow: 0 10px 26px rgba(16,24,40,0.12);
+  display:grid; place-items:center;
+  cursor:pointer;
+}
+.car-btn:hover{ background: #fff; }
+.car-btn.left{ left: -6px; }
+.car-btn.right{ right: -6px; }
+
+/* Tools */
+.tools-grid{ display:grid; grid-template-columns: 1.2fr 0.8fr; gap: 14px; }
+.panel{
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: calc(var(--radius) + 6px);
+  box-shadow: var(--shadow);
+  overflow:hidden;
+}
+.panel .pad{ padding: 18px; }
+.panel h3{ margin:0 0 8px; font-size: 18px; letter-spacing: -0.02em; }
+.panel p{ margin:0 0 12px; color: var(--muted); }
+.list{ display:grid; gap: 10px; margin-top: 10px; }
+.list a{
+  display:flex;
+  align-items:flex-start;
+  gap: 10px;
+  padding: 12px;
+  border: 1px solid var(--border);
+  border-radius: 14px;
+  background: linear-gradient(180deg, rgba(2,131,141,0.05), rgba(255,255,255,0.0));
+}
+.list a:hover{ text-decoration:none; border-color: rgba(2,131,141,0.22); }
+.list .mini{
+  width: 36px; height: 36px; border-radius: 14px;
+  background: rgba(2,131,141,0.10);
+  display:grid; place-items:center;
+  flex: 0 0 auto;
+}
+.list strong{ display:block; font-size: 13px; }
+.list span{ display:block; color: var(--muted); font-size: 12px; margin-top: 2px; }
+
+/* Recommended reads tabs */
+.tabs{
+  display:flex;
+  flex-wrap: wrap;
+  gap: 8px;
+  margin: 8px 0 14px;
+}
+.tab{
+  border: 1px solid var(--border);
+  background: rgba(255,255,255,0.75);
+  padding: 10px 12px;
+  border-radius: 999px;
+  font-weight: 900;
+  font-size: 13px;
+  cursor:pointer;
+}
+.tab[aria-selected="true"]{
+  background: rgba(2,131,141,0.12);
+  border-color: rgba(2,131,141,0.25);
+}
+.tab:focus{ outline: 3px solid rgba(10,132,255,0.22); outline-offset: 2px; }
+
+.grid{ display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
+.article{ position: relative; }
+.article .thumb{ height: 140px; }
+.article .meta{ display:flex; gap: 10px; align-items:center; margin-top: 10px; }
+.reading{ font-size: 12px; color: var(--muted); font-weight: 800; }
+.article h4{ margin: 10px 0 0; font-size: 15px; letter-spacing:-0.01em; }
+
+/* Trust pillars */
+.pillars{ display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
+.pillar{
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 14px;
+  box-shadow: 0 14px 26px rgba(16,24,40,0.06);
+}
+.pillar .top{ display:flex; align-items:center; gap: 10px; }
+.glyph{ width: 36px; height: 36px; border-radius: 14px; background: rgba(255,107,94,0.14); display:grid; place-items:center; }
+.pillar h4{ margin: 0; font-size: 14px; letter-spacing: -0.01em; }
+.pillar p{ margin: 10px 0 0; color: var(--muted); font-size: 13px; }
+
+/* Program + video cards */
+.grid4{ display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
+.program .thumb{ height: 120px; }
+.video .thumb{ height: 140px; position: relative; }
+.play{
+  position:absolute;
+  inset:auto auto 12px 12px;
+  width: 44px; height: 44px;
+  border-radius: 999px;
+  background: rgba(255,255,255,0.92);
+  border: 1px solid rgba(2,131,141,0.22);
+  box-shadow: 0 12px 26px rgba(16,24,40,0.14);
+  display:grid; place-items:center;
+}
+
+/* Footer */
+footer{
+  margin-top: 48px;
+  border-top: 1px solid var(--border);
+  background: linear-gradient(180deg, rgba(2,131,141,0.06), rgba(255,255,255,0.0));
+}
+.footer-grid{ display:grid; grid-template-columns: 1.3fr 0.7fr; gap: 14px; padding: 22px 0; }
+.footer-grid p{ margin:0 0 12px; color: var(--muted); }
+.footer-links{
+  display:flex;
+  flex-wrap: wrap;
+  gap: 10px 14px;
+  padding: 10px 0 0;
+  border-top: 1px solid var(--border);
+  margin-top: 14px;
+}
+.footer-links a{ font-weight: 800; color: #0b3940; font-size: 13px; }
+.legal{ color: var(--muted); font-size: 12px; padding: 12px 0 26px; }
+.social{ display:flex; flex-wrap: wrap; gap: 10px; }
+.social a{ border:1px solid var(--border); background: rgba(255,255,255,0.65); padding: 8px 10px; border-radius: 999px; font-weight: 900; font-size: 12px; }
+
+/* Responsive */
+@media (max-width: 980px){
+  .search{ display:none; }
+  .mega-inner{ grid-template-columns: 1fr; }
+  .mega-aside{ border-right: 0; border-bottom: 1px solid var(--border); }
+  .mega-grid{ grid-template-columns: repeat(2, minmax(0,1fr)); }
+  .hero{ grid-template-columns: 1fr; }
+  .hero-card h1{ font-size: 30px; }
